  "id" int4 NOT NULL DEFAULT nextval('t_ds_process_definition_id_sequence'::regclass),
  "code" int8 NOT NULL,
  "name" varchar(255) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
