  "flag" int4,
  "timeout" int4 DEFAULT 0,
  "execution_type" int4 DEFAULT 0,
  "create_time" timestamp(6),
  "update_time" timestamp(6)
)
;
ALTER TABLE "public"."t_ds_process_definition" OWNER TO "root";

