DROP TABLE IF EXISTS "public"."t_ds_process_instance";
CREATE TABLE "public"."t_ds_process_instance" (
  "id" int4 NOT NULL DEFAULT nextval('t_ds_process_instance_id_sequence'::regclass),
  "name" varchar(255) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "process_definition_code" int8,
  "process_definition_version" int4 NOT NULL DEFAULT 1,
  "project_code" int8,
  "state" int4,
  "state_history" text COLLATE "pg_catalog"."default",
  "recovery" int4,
  "start_time" timestamp(6),
  "end_time" timestamp(6),
  "run_times" int4,
  "host" varchar(135) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "command_type" int4,
  "command_param" text COLLATE "pg_catalog"."default",
  "task_depend_type" int4,
  "max_try_times" int4 DEFAULT 0,
  "failure_strategy" int4 DEFAULT 0,
  "warning_type" int4 DEFAULT 0,
  "warning_group_id" int4,
  "schedule_time" timestamp(6),
  "command_start_time" timestamp(6),
  "global_params" text COLLATE "pg_catalog"."default",
  "process_instance_json" text COLLATE "pg_catalog"."default",
  "flag" int4 DEFAULT 1,
  "update_time" timestamp(6),
  "is_sub_process" int4 DEFAULT 0,
  "executor_id" int4 NOT NULL,
  "executor_name" varchar(64) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "history_cmd" text COLLATE "pg_catalog"."default",
  "dependence_schedule_times" text COLLATE "pg_catalog"."default",
  "process_instance_priority" int4 DEFAULT 2,
  "worker_group" varchar(255) COLLATE "pg_catalog"."default",
  "environment_code" int8 DEFAULT '-1'::bigint,
  "timeout" int4 DEFAULT 0,
  "tenant_code" varchar(64) COLLATE "pg_catalog"."default" DEFAULT 'default'::character varying,
  "var_pool" text COLLATE "pg_catalog"."default",
  "dry_run" int4 DEFAULT 0,
  "next_process_instance_id" int4 DEFAULT 0,
  "restart_time" timestamp(6),
  "test_flag" int4
)
;
ALTER TABLE "public"."t_ds_process_instance" OWNER TO "root";

