INSERT INTO "public"."t_ds_project" ("id", "name", "code", "description", "user_id", "flag", "create_time", "update_time") VALUES (35, '监测数据组', 152317955043040, '监测数据处理项目组，聚焦项目运行中的设备与系统监测数据（如传感器、日志、性能指标），负责本类数据的采集接入、清洗转换、模型构建与统一管理，支撑状态监控、异常预警及运维分析类数据服务。', 1, 1, '2025-09-18 14:53:28.949', '2025-09-22 19:21:26.121');
INSERT INTO "public"."t_ds_project" ("id", "name", "code", "description", "user_id", "flag", "create_time", "update_time") VALUES (34, '基础数据组', 152317790975712, '基础数据处理项目组，用于统一开展项目内各类基础数据的采集、治理与清洗工作，保障数据质量与一致性。', 1, 1, '2025-09-18 14:50:42.706', '2025-09-22 19:21:31.721');
INSERT INTO "public"."t_ds_project" ("id", "name", "code", "description", "user_id", "flag", "create_time", "update_time") VALUES (36, '业务数据组', 152317966055136, '业务数据处理项目组，围绕水利项目核心业务流程，负责水量调度、工程巡检、防汛工单、水文记录等结构化数据的汇聚整合、标准治理与加工处理，支撑业务统计、过程追溯与管理决策类数据应用。', 1, 1, '2025-09-18 14:53:39.703', '2025-09-22 19:21:35.701');
