INSERT INTO "public"."t_ds_task_definition" ("id", "code", "name", "version", "description", "project_code", "user_id", "task_type", "task_execute_type", "task_params", "flag", "is_cache", "task_priority", "worker_group", "environment_code", "fail_retry_times", "fail_retry_interval", "timeout_flag", "timeout_notify_strategy", "timeout", "delay_time", "task_group_id", "task_group_priority", "resource_ids", "cpu_quota", "memory_max", "create_time", "update_time") VALUES (89, 152672440882496, 'Hive_水位日统计报表', 2, '【离线计算】 查询水位实时数据，生成每日统计报表    （Hive 非完全部署，任务无法运行）', 152317790975712, 1, 'SQL', 0, '{"localParams":[],"resourceList":[],"type":"HIVE","sql":"-- ========== 1) 源：MySQL 水位明细 ==========\r\nCREATE TEMPORARY VIEW hyd_water_level_src\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''hyd_water_level'',\r\n  user ''root'',\r\n  password ''sfdjfFF#s2332'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 2) 可选维度：站点表（如没有可保留，后续会自动降级为用 station_code 代替名称）==========\r\n-- 期望列：station_id BIGINT, station_code VARCHAR, station_name VARCHAR\r\nCREATE TEMPORARY VIEW hyd_station_dim\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''hyd_station'',                       -- 没有就保持这样；后续 LEFT JOIN + COALESCE 兼容\r\n  user ''root'',\r\n  password ''sfdjfFF#s2332'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 3) 目标：Doris 报表（通过 MySQL 协议）==========\r\nCREATE TABLE IF NOT EXISTS dws_station_water_day_report_jdbc\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://host.docker.internal:9030/dws?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''dws_station_water_day_report'',\r\n  user ''root'',\r\n  password ''InC3tmU4bijT4vkl'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 4) 计算“日平均水位”并写入目标 ==========\r\nWITH base AS (\r\n  SELECT\r\n    wl.station_code,\r\n    COALESCE(wl.obs_date, CAST(wl.obs_time AS DATE)) AS stat_date,\r\n    CAST(wl.water_level_m AS DOUBLE)                  AS water_level_m\r\n  FROM hyd_water_level_src wl\r\n  WHERE wl.water_level_m IS NOT NULL\r\n),\r\nday_avg AS (\r\n  SELECT\r\n    station_code,\r\n    stat_date,\r\n    AVG(water_level_m) AS avg_level_day\r\n  FROM base\r\n  GROUP BY station_code, stat_date\r\n)\r\n\r\nINSERT INTO dws_station_water_day_report_jdbc\r\nSELECT\r\n  -- station_id：有维表用维表，没有则置 NULL\r\n  COALESCE(CAST(s.station_id AS BIGINT), CAST(NULL AS BIGINT))             AS station_id,\r\n  -- station_name：有维表用维表名称，没有则用 station_code 顶上\r\n  COALESCE(CAST(s.station_name AS STRING), CAST(d.station_code AS STRING)) AS station_name,\r\n  -- 写入日平均（保留三位小数），沿用目标表列名 avg_level_year\r\n  CAST(ROUND(d.avg_level_day, 3) AS DECIMAL(10,3))                          AS avg_level_year,\r\n  CAST(d.stat_date AS DATE)                                                 AS stat_date\r\nFROM day_avg d\r\nLEFT JOIN hyd_station_dim s\r\n  ON s.station_code = d.station_code;","sqlType":"0","preStatements":[],"postStatements":[],"displayRows":10,"datasources":{"password":"qData123","database":"default","other":{"hive.resultset.use.unique.column.names":false},"port":10000,"connectType":"ORACLE_SERVICE_NAME","host":"hive","type":"HIVE","userName":"admin"}}', 1, 0, 2, 'default', 133155949418208, 0, 1, NULL, NULL, 0, 0, 0, 0, NULL, -1, -1, '2025-09-22 18:03:55.894', '2025-09-22 18:06:41.785');
INSERT INTO "public"."t_ds_task_definition" ("id", "code", "name", "version", "description", "project_code", "user_id", "task_type", "task_execute_type", "task_params", "flag", "is_cache", "task_priority", "worker_group", "environment_code", "fail_retry_times", "fail_retry_interval", "timeout_flag", "timeout_notify_strategy", "timeout", "delay_time", "task_group_id", "task_group_priority", "resource_ids", "cpu_quota", "memory_max", "create_time", "update_time") VALUES (91, 152672766952768, 'MySQL_水位日统计', 1, '【MySQL  存储过程】查询水位实时数据，生成每日统计报表  ', 152317790975712, 1, 'SQL', 0, '{"localParams":[],"resourceList":[],"type":"MYSQL","sql":"/* ===========================================================\r\n   环境准备（按需修改库名）\r\n   =========================================================== */\r\n-- 可选：使用你的业务库\r\nCREATE DATABASE IF NOT EXISTS hydrology DEFAULT CHARACTER SET utf8mb4;\r\nUSE hydrology;\r\n\r\n/* ===========================================================\r\n   1) 报表表（日平均水位）\r\n   - 以 (station_code, stat_date) 做唯一键，兼容无维表场景\r\n   - 如存在维表，会同步写入 station_id / station_name\r\n   =========================================================== */\r\nCREATE TABLE IF NOT EXISTS dws_station_water_day_report (\r\n  station_code   VARCHAR(64)  NOT NULL COMMENT ''测站编码'',\r\n  station_id     BIGINT                COMMENT ''测站ID（有维表时填充）'',\r\n  station_name   VARCHAR(128)          COMMENT ''测站名称（有维表时填充；无维表时=station_code）'',\r\n  avg_level_day  DECIMAL(10,3)         COMMENT ''日平均水位(米)'',\r\n  stat_date      DATE         NOT NULL COMMENT ''统计日期'',\r\n  PRIMARY KEY (station_code, stat_date),\r\n  KEY idx_stat_date (stat_date),\r\n  KEY idx_station_id (station_id)\r\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=''站点水位日统计（日均）'';\r\n\r\n/* ===========================================================\r\n   2) 单日报表过程\r\n   - 输入：p_stat_date（统计yyyy-MM-dd）\r\n   - 逻辑：\r\n       取 obs_date，否则取 DATE(obs_time) 作为统计日期\r\n       按 (station_code, stat_date) 聚合 AVG(water_level_m)\r\n       LEFT JOIN hyd_station（如存在）填充 id/name\r\n       用 ON DUPLICATE KEY 做 upsert\r\n   =========================================================== */\r\nDELIMITER $$\r\n\r\nDROP PROCEDURE IF EXISTS prc_gen_water_day_report $$\r\nCREATE PROCEDURE prc_gen_water_day_report(IN p_stat_date DATE)\r\nBEGIN\r\n  /*\r\n    说明：\r\n    - 若不存在 hyd_station 表，LEFT JOIN 返回 NULL，不影响执行；\r\n      station_id 将为 NULL，station_name 用 station_code 兜底。\r\n    - hyd_water_level 建议在 hydrology 库中（按需改库名前缀）。\r\n  */\r\n  INSERT INTO dws_station_water_day_report\r\n  (\r\n    station_code, station_id, station_name, avg_level_day, stat_date\r\n  )\r\n  SELECT\r\n    wl.station_code                                                AS station_code,\r\n    s.station_id                                                   AS station_id,               -- 可能为 NULL\r\n    COALESCE(s.station_name, wl.station_code)                      AS station_name,             -- 兜底\r\n    ROUND(AVG(CAST(wl.water_level_m AS DECIMAL(10,3))), 3)         AS avg_level_day,\r\n    p_stat_date                                                    AS stat_date\r\n  FROM hydrology.hyd_water_level wl\r\n  LEFT JOIN hydrology.hyd_station s\r\n    ON s.station_code = wl.station_code\r\n  WHERE\r\n      (CASE\r\n         WHEN wl.obs_date IS NOT NULL THEN wl.obs_date\r\n         ELSE DATE(wl.obs_time)\r\n       END) = p_stat_date\r\n    AND wl.water_level_m IS NOT NULL\r\n  GROUP BY wl.station_code, s.station_id, COALESCE(s.station_name, wl.station_code)\r\n  ON DUPLICATE KEY UPDATE\r\n      station_id     = VALUES(station_id),\r\n      station_name   = VALUES(station_name),\r\n      avg_level_day  = VALUES(avg_level_day);\r\nEND $$\r\nDELIMITER ;\r\n\r\n/* ===========================================================\r\n   3) 区间报表过程（含首尾）\r\n   =========================================================== */\r\nDELIMITER $$\r\n\r\nDROP PROCEDURE IF EXISTS prc_gen_water_day_report_range $$\r\nCREATE PROCEDURE prc_gen_water_day_report_range(IN p_begin_date DATE, IN p_end_date DATE)\r\nBEGIN\r\n  DECLARE v_day DATE;\r\n\r\n  IF p_begin_date IS NULL OR p_end_date IS NULL THEN\r\n    SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''起止日期不可为空'';\r\n  END IF;\r\n\r\n  IF p_begin_date > p_end_date THEN\r\n    SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''起始日期不能晚于截止日期'';\r\n  END IF;\r\n\r\n  SET v_day = p_begin_date;\r\n  WHILE v_day <= p_end_date DO\r\n    CALL prc_gen_water_day_report(v_day);\r\n    SET v_day = DATE_ADD(v_day, INTERVAL 1 DAY);\r\n  END WHILE;\r\nEND $$\r\nDELIMITER ;\r\n\r\n/* ===========================================================\r\n   4) 使用示例\r\n   =========================================================== */\r\n-- 生成某一天（例如 2025-01-01）\r\nCALL prc_gen_water_day_report(''2025-01-01'');\r\n\r\n-- 生成一段时间（例如 2025-01-01 ~ 2025-01-07）\r\nCALL prc_gen_water_day_report_range(''2025-01-01'', ''2025-01-07'');\r\n\r\n-- 校验\r\nSELECT *\r\nFROM dws_station_water_day_report\r\nORDER BY stat_date DESC, station_code\r\nLIMIT 20;\r\n\r\n/* ===========================================================\r\n   5) （可选）事件调度：每天 00:10 生成“昨日日报”\r\n   - 需要：SET GLOBAL event_scheduler = ON;\r\n   - 如不需要可删除此段\r\n   =========================================================== */\r\nSET GLOBAL event_scheduler = ON;\r\n\r\nCREATE EVENT IF NOT EXISTS evt_gen_water_day_report_yesterday\r\nON SCHEDULE EVERY 1 DAY\r\nSTARTS TIMESTAMP(CURRENT_DATE, ''00:10:00'')\r\nDO\r\n  CALL prc_gen_water_day_report(DATE_SUB(CURDATE(), INTERVAL 1 DAY));\r\n","sqlType":"0","preStatements":[],"postStatements":[],"displayRows":10,"datasources":{"password":"sfdjfFF#s2332","database":"hydrology","other":{},"port":3306,"connectType":"ORACLE_SERVICE_NAME","host":"mysql57","type":"MYSQL","userName":"root"}}', 1, 0, 2, 'default', 133155949418208, 0, 1, NULL, NULL, 0, 0, 0, 0, NULL, -1, -1, '2025-09-22 18:13:05.613', '2025-09-22 18:13:05.613');
INSERT INTO "public"."t_ds_task_definition" ("id", "code", "name", "version", "description", "project_code", "user_id", "task_type", "task_execute_type", "task_params", "flag", "is_cache", "task_priority", "worker_group", "environment_code", "fail_retry_times", "fail_retry_interval", "timeout_flag", "timeout_notify_strategy", "timeout", "delay_time", "task_group_id", "task_group_priority", "resource_ids", "cpu_quota", "memory_max", "create_time", "update_time") VALUES (92, 152673322082624, '转化_水位预警等级校验', 2, '', 152317790975712, 1, 'SUB_PROCESS', 0, '{"localParams":[],"resourceList":[],"processDefinitionCode":152439162752320}', 1, 0, 2, 'default', 133155949418208, 0, 1, NULL, NULL, 0, 0, 0, 0, NULL, -1, -1, '2025-09-22 18:19:24.225', '2025-09-22 18:19:42.892');
