-- ----------------------------
-- Table structure for t_ds_task_definition_log
-- ----------------------------
DROP TABLE IF EXISTS "public"."t_ds_task_definition_log";
CREATE TABLE "public"."t_ds_task_definition_log" (
  "id" int4 NOT NULL DEFAULT nextval('t_ds_task_definition_log_id_sequence'::regclass),
  "code" int8 NOT NULL,
  "name" varchar(255) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "version" int4 NOT NULL DEFAULT 1,
  "description" text COLLATE "pg_catalog"."default",
  "project_code" int8,
  "user_id" int4,
  "task_type" varchar(50) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "task_execute_type" int4 DEFAULT 0,
  "task_params" text COLLATE "pg_catalog"."default",
  "flag" int4,
  "is_cache" int4 DEFAULT 0,
  "task_priority" int4 DEFAULT 2,
  "worker_group" varchar(255) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "environment_code" int8 DEFAULT '-1'::bigint,
  "fail_retry_times" int4,
  "fail_retry_interval" int4,
  "timeout_flag" int4,
  "timeout_notify_strategy" int4,
  "timeout" int4 DEFAULT 0,
  "delay_time" int4 DEFAULT 0,
  "resource_ids" text COLLATE "pg_catalog"."default",
  "operator" int4,
  "task_group_id" int4,
  "task_group_priority" int4 DEFAULT 0,
  "operate_time" timestamp(6),
  "cpu_quota" int4 NOT NULL DEFAULT '-1'::integer,
  "memory_max" int4 NOT NULL DEFAULT '-1'::integer,
  "create_time" timestamp(6),
  "update_time" timestamp(6)
)
;
ALTER TABLE "public"."t_ds_task_definition_log" OWNER TO "root";

