INSERT INTO "public"."t_ds_task_definition_log" ("id", "code", "name", "version", "description", "project_code", "user_id", "task_type", "task_execute_type", "task_params", "flag", "is_cache", "task_priority", "worker_group", "environment_code", "fail_retry_times", "fail_retry_interval", "timeout_flag", "timeout_notify_strategy", "timeout", "delay_time", "resource_ids", "operator", "task_group_id", "task_group_priority", "operate_time", "cpu_quota", "memory_max", "create_time", "update_time") VALUES (145, 152672440882496, 'Hive_水位日统计报表', 1, '【离线计算】 查询水位实时数据，生成每日统计报表    （Hive 非完全部署，任务无法运行）', 152317790975712, 1, 'SQL', 0, '{"localParams":[],"resourceList":[],"type":"HIVE","sql":"-- ========== 1) 源：MySQL 水位明细 ==========\r\nCREATE TEMPORARY VIEW hyd_water_level_src\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''hyd_water_level'',\r\n  user ''root'',\r\n  password ''sfdjfFF#s2332'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 2) 可选维度：站点表（如没有可保留，后续会自动降级为用 station_code 代替名称）==========\r\n-- 期望列：station_id BIGINT, station_code VARCHAR, station_name VARCHAR\r\nCREATE TEMPORARY VIEW hyd_station_dim\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''hyd_station'',                       -- 没有就保持这样；后续 LEFT JOIN + COALESCE 兼容\r\n  user ''root'',\r\n  password ''sfdjfFF#s2332'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 3) 目标：Doris 报表（通过 MySQL 协议）==========\r\nCREATE TABLE IF NOT EXISTS dws_station_water_day_report_jdbc\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://host.docker.internal:9030/dws?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''dws_station_water_day_report'',\r\n  user ''root'',\r\n  password ''InC3tmU4bijT4vkl'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 4) 计算“日平均水位”并写入目标 ==========\r\nWITH base AS (\r\n  SELECT\r\n    wl.station_code,\r\n    COALESCE(wl.obs_date, CAST(wl.obs_time AS DATE)) AS stat_date,\r\n    CAST(wl.water_level_m AS DOUBLE)                  AS water_level_m\r\n  FROM hyd_water_level_src wl\r\n  WHERE wl.water_level_m IS NOT NULL\r\n),\r\nday_avg AS (\r\n  SELECT\r\n    station_code,\r\n    stat_date,\r\n    AVG(water_level_m) AS avg_level_day\r\n  FROM base\r\n  GROUP BY station_code, stat_date\r\n)\r\n\r\nINSERT INTO dws_station_water_day_report_jdbc\r\nSELECT\r\n  -- station_id：有维表用维表，没有则置 NULL\r\n  COALESCE(CAST(s.station_id AS BIGINT), CAST(NULL AS BIGINT))             AS station_id,\r\n  -- station_name：有维表用维表名称，没有则用 station_code 顶上\r\n  COALESCE(CAST(s.station_name AS STRING), CAST(d.station_code AS STRING)) AS station_name,\r\n  -- 写入日平均（保留三位小数），沿用目标表列名 avg_level_year\r\n  CAST(ROUND(d.avg_level_day, 3) AS DECIMAL(10,3))                          AS avg_level_year,\r\n  CAST(d.stat_date AS DATE)                                                 AS stat_date\r\nFROM day_avg d\r\nLEFT JOIN hyd_station_dim s\r\n  ON s.station_code = d.station_code;","sqlType":"0","preStatements":[],"postStatements":[],"displayRows":10,"datasources":{"password":"qData123","database":"default","other":{"hive.resultset.use.unique.column.names":false},"port":10000,"connectType":"ORACLE_SERVICE_NAME","host":"hive","type":"HIVE","userName":"admin"}}', 1, 0, 2, 'default', 133155949418208, 0, 1, NULL, NULL, 0, 0, NULL, 1, 0, 0, '2025-09-22 18:03:55.894', -1, -1, '2025-09-22 18:03:55.894', '2025-09-22 18:03:55.894');
