CREATE TABLE "public"."t_ds_task_instance" (
  "id" int4 NOT NULL DEFAULT nextval('t_ds_task_instance_id_sequence'::regclass),
  "name" varchar(255) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "task_type" varchar(50) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "task_execute_type" int4 DEFAULT 0,
  "task_code" int8 NOT NULL,
  "task_definition_version" int4 NOT NULL DEFAULT 1,
  "process_instance_id" int4,
  "process_instance_name" varchar(255) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "project_code" int8,
  "state" int4,
  "submit_time" timestamp(6),
  "start_time" timestamp(6),
  "end_time" timestamp(6),
  "host" varchar(135) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "execute_path" varchar(200) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "log_path" text COLLATE "pg_catalog"."default",
  "alert_flag" int4,
  "retry_times" int4 DEFAULT 0,
  "pid" int4,
  "app_link" text COLLATE "pg_catalog"."default",
  "task_params" text COLLATE "pg_catalog"."default",
  "flag" int4 DEFAULT 1,
  "is_cache" int4 DEFAULT 0,
  "cache_key" varchar(200) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "retry_interval" int4,
  "max_retry_times" int4,
  "task_instance_priority" int4,
  "worker_group" varchar(255) COLLATE "pg_catalog"."default",
  "environment_code" int8 DEFAULT '-1'::bigint,
  "environment_config" text COLLATE "pg_catalog"."default",
  "executor_id" int4,
  "executor_name" varchar(64) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "first_submit_time" timestamp(6),
  "delay_time" int4 DEFAULT 0,
  "task_group_id" int4,
